// spec: specs/addbusiness-draft-save.md (2.1–2.2) · кейс: .qa/tests/addbusiness-draft-save/ADDBIZ-DRAFT-02.md · #0c6087
// ПРОД, ничего не пишем: POST/PATCH business черновика отвечаются локально, PATCH переключается на 500; прочие не-GET — abort.
import { test, expect } from '@playwright/test';
import { LOAD, DRAFT_ERR, interceptDraft, fillStep1AndNext, step2EmptyNext, nextWithPatch } from './draft.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('Мастер «פרסום עסק למכירה» — ошибка сохранения черновика (#0c6087)', () => {
  for (const device of ['@desktop', '@android']) {
    test(`PATCH черновика 500 — «${DRAFT_ERR}», мастер продолжается #0c6087 ${device} @prod-safe`, async ({ page }) => {
      const ctl = await interceptDraft(page);
      await fillStep1AndNext(page, ctl);
      await step2EmptyNext(page);

      ctl.patchStatus = 500;
      await nextWithPatch(page, ctl, '3→4 (ответ 500)');

      // «מה רצוי»: «אם השמירה נכשלת — להציג למשתמש הודעה»; текст и «אך תוכל להמשיך» — комментарий программиста
      const msg = page.getByText(DRAFT_ERR).first();
      await expect(msg, 'сообщение об ошибке сохранения черновика').toBeVisible(LOAD);
      const box = await msg.boundingBox();
      const { vw, vh } = await page.evaluate(() => ({ vw: document.documentElement.clientWidth || window.innerWidth, vh: window.innerHeight }));
      expect(box, 'у сообщения есть прямоугольник').not.toBeNull();
      expect(box!.y, 'сообщение в верхней части экрана').toBeLessThan(vh / 3);
      expect(box!.x, 'не за левым краем').toBeGreaterThanOrEqual(0);
      expect(box!.x + box!.width, 'не за правым краем').toBeLessThanOrEqual(vw + 0.5);

      await expect(page.getByText('בחר חבילת פרסום'), 'шаг 4 открыт — продолжить можно').toBeVisible(LOAD);
      expect(ctl.passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }
});
